\providecommand{\t}{1}
\begin{tikzpicture}[line join=round, line cap=round, >=Stealth, font=\small]
  \tikzset{layer/.style={}, declare function={
    clp(\x,\a,\b)=max(0,min(1,(\x-\a)/(\b-\a)));
    smoothstep(\x)=\x*\x*(3-2*\x);
    smootherstep(\x)=\x*\x*\x*(\x*(6*\x-15)+10);
    easeout(\x)=1-(1-\x)*(1-\x)*(1-\x);
    bump(\x)=sin(\x*180)^2;
    appear(\x,\a,\b)=smoothstep(clp(\x,\a,\b));
    lerp(\a,\b,\p)=\a+(\b-\a)*\p;
  }}
  \pgfmathsetmacro{\tval}{\t}

  % Khóa cứng khung nhìn (Fixed Bounding Box chống giật khung giữa các frame)
  \path (-4.4, -2.6) rectangle (4.8, 4.5);

  \definecolor{mnInk}{HTML}{1B2A44}
  \definecolor{mnTeal}{HTML}{0FA39A}
  \definecolor{mnOrange}{HTML}{F07C00}
  \definecolor{mnPurple}{HTML}{7C3AED}

  % Tọa độ tham số bảo toàn ràng buộc cho phép nạp ngược về MinNote
  \coordinate (A) at (-2.8, 0.2);
  \coordinate (B) at (-1.7, -1.8);
  \coordinate (C) at (1.7, -2.2);
  \coordinate (D) at (3.2, 0.5);
  \coordinate (S) at (0.8, 3.8);
  \coordinate (O) at (intersection of A--C and B--D);
  \coordinate (M) at ($(S)!0.5!(C)$);
  \coordinate (N) at ($(S)!0.5!(D)$);
  \coordinate (K) at (intersection of A--M and S--O);
  \coordinate (I) at (intersection of B--K and S--D);
  \coordinate (Ax) at ($(A)+0.95*(C)-0.95*(D)$);

  % Biến tiến trình trên dòng thời gian liên tục t in [0, 1] (dành [0.92, 1.00] giữ cuối kết vòng lặp)
  \pgfmathsetmacro{\pBase}{smootherstep(clp(\tval, 0.02, 0.16))}
  \pgfmathsetmacro{\pPyr}{smootherstep(clp(\tval, 0.16, 0.30))}
  \pgfmathsetmacro{\pDiag}{smoothstep(clp(\tval, 0.30, 0.42))}
  \pgfmathsetmacro{\pSO}{smoothstep(clp(\tval, 0.42, 0.52))}
  \pgfmathsetmacro{\gSO}{bump(clp(\tval, 0.46, 0.56))}
  \pgfmathsetmacro{\pAM}{smoothstep(clp(\tval, 0.54, 0.63))}
  \pgfmathsetmacro{\pBI}{smoothstep(clp(\tval, 0.63, 0.72))}
  \pgfmathsetmacro{\bI}{bump(clp(\tval, 0.70, 0.79))}
  \pgfmathsetmacro{\pSec}{smootherstep(clp(\tval, 0.74, 0.84))}
  \pgfmathsetmacro{\opFill}{appear(\tval, 0.80, 0.87)}
  \pgfmathsetmacro{\pAx}{smootherstep(clp(\tval, 0.85, 0.93))}
  \pgfmathsetmacro{\bEnd}{bump(clp(\tval, 0.91, 0.99))}

  % Layer 0: Camera / Viewport Scope
  \pgfmathsetmacro{\camFocus}{bump(clp(\tval, 0.50, 0.84))}
  \pgfmathsetmacro{\camScale}{1.0 + 0.08 * \camFocus}
  \begin{scope}[layer=camera, scale=\camScale, transform shape]

    % Layer 1: Ambient (Miền tô thiết diện bán trong suốt)
    \begin{scope}[layer=ambient]
      \fill[mnOrange, opacity={0.14 * \opFill}] (A) -- (B) -- (M) -- (I) -- cycle;
    \end{scope}

    % Layer 2: Geometry (Dựng từng cạnh tiến triển theo biến tval)
    \begin{scope}[layer=geometry]
      % Đáy ABCD
      \ifdim \pBase pt > 0.005pt
        \draw[mnInk, line width=1.1pt] (A) -- ($(A)!\pBase!(B)$);
        \draw[mnInk, line width=1.1pt] (B) -- ($(B)!\pBase!(C)$);
        \draw[mnInk, line width=1.1pt] (C) -- ($(C)!\pBase!(D)$);
        \draw[mnInk, dashed, line width=0.95pt] (A) -- ($(A)!\pBase!(D)$);
      \fi

      % Cạnh bên SA, SB, SC, SD
      \ifdim \pPyr pt > 0.005pt
        \draw[mnInk, line width=1.1pt] (S) -- ($(S)!\pPyr!(A)$);
        \draw[mnInk, line width=1.1pt] (S) -- ($(S)!\pPyr!(B)$);
        \draw[mnInk, line width=1.1pt] (S) -- ($(S)!\pPyr!(C)$);
        \draw[mnInk, line width=1.1pt] (S) -- ($(S)!\pPyr!(D)$);
      \fi

      % Đường chéo AC, BD
      \ifdim \pDiag pt > 0.005pt
        \draw[mnInk!75, dashed, line width=0.85pt] (A) -- ($(A)!\pDiag!(C)$);
        \draw[mnInk!75, dashed, line width=0.85pt] (B) -- ($(B)!\pDiag!(D)$);
      \fi

      % Câu a: Giao tuyến SO kèm hào quang glow
      \ifdim \pSO pt > 0.005pt
        \draw[mnTeal!35, line width=3.4pt, opacity={0.55 * \gSO}] (S) -- ($(S)!\pSO!(O)$);
        \draw[mnTeal, dashed, line width=1.25pt] (S) -- ($(S)!\pSO!(O)$);
      \fi

      % Câu b: Dựng K = AM ∩ SO và I = BK ∩ SD
      \ifdim \pAM pt > 0.005pt
        \draw[mnInk!80, dashed, line width=0.9pt] (A) -- ($(A)!\pAM!(M)$);
      \fi
      \ifdim \pBI pt > 0.005pt
        \draw[mnInk!80, dashed, line width=0.9pt] (B) -- ($(B)!\pBI!(I)$);
      \fi

      % Viền thiết diện ABMI
      \ifdim \pSec pt > 0.005pt
        \draw[mnOrange, line width=1.4pt] (B) -- ($(B)!\pSec!(M)$);
        \draw[mnOrange, line width=1.4pt] (M) -- ($(M)!\pSec!(I)$);
        \draw[mnOrange, dashed, line width=1.2pt] (A) -- ($(A)!\pSec!(I)$);
      \fi

      % Câu c: MN // CD và giao tuyến Ax // CD
      \ifdim \pAx pt > 0.005pt
        \draw[mnPurple!80, line width=1.0pt] (M) -- ($(M)!\pAx!(N)$);
        \draw[mnPurple!30, line width=3.4pt, opacity={0.55 * \bEnd}] (A) -- ($(A)!\pAx!(Ax)$);
        \draw[mnPurple, line width=1.35pt] (A) -- ($(A)!\pAx!(Ax)$);
      \fi
    \end{scope}

    % Layer 3: Graphs (dành cho quỹ đạo/đồ thị phụ nếu có)
    \begin{scope}[layer=graphs]
    \end{scope}

    % Layer 4: Annotations (Điểm, Nhãn và Hộp kết luận)
    \begin{scope}[layer=annotations]
      \foreach \p/\pos in {A/left, B/below left, C/below right, D/right} {
        \fill[mnInk, opacity={appear(\tval, 0.01, 0.08)}] (\p) circle (1.4pt) node[\pos] {$\p$};
      }
      \fill[mnInk, opacity={appear(\tval, 0.15, 0.21)}] (S) circle (1.5pt) node[above] {$S$};
      \fill[mnTeal, opacity={appear(\tval, 0.40, 0.46)}] (O) circle (1.6pt) node[below] {$O$};
      \fill[mnInk, opacity={appear(\tval, 0.52, 0.57)}] (M) circle (1.4pt) node[right] {$M$};
      \fill[mnInk, opacity={appear(\tval, 0.52, 0.57)}] (N) circle (1.4pt) node[above right] {$N$};
      \fill[mnTeal, opacity={appear(\tval, 0.61, 0.65)}] (K) circle (1.5pt) node[left] {$K$};
      \fill[mnOrange, opacity={appear(\tval, 0.70, 0.75)}] (I) circle ({1.6pt + 0.8pt * \bI}) node[above right] {$I$};
      \node[mnPurple, font=\bfseries, below left, opacity={appear(\tval, 0.89, 0.94)}] at (Ax) {$x$};
    \end{scope}

  \end{scope}
\end{tikzpicture}

